export function productById(id: string): Product | undefined {
  return products.find((product) => product.id === id);
}

export function productsByMarket(marketId: string): Product[] {
  return products.filter((product) => product.marketId === marketId);
}

export function productsBySeller(sellerId: string): Product[] {
  return products.filter((product) => product.sellerId === sellerId);
}

export function productsByCategory(slug: string): Product[] {
  return products.filter((product) => product.category === slug);
}

/** Listed today and still available. */
export function newToday(): Product[] {
  return products.filter((product) => product.addedDaysAgo === 0 && product.status === 'Saatavilla');
}

export function newTodayCount(marketId: string): number {
  return newToday().filter((product) => product.marketId === marketId).length;
}
